def lookup_names(connection, prefix):
    rows = connection.execute('SELECT name FROM people WHERE substr(name, 1, ?) = ? ORDER BY name', (len(prefix), prefix))
    return [row[0] for row in rows]

def parse_count(text):
    import json
    value = json.loads(text)
    if not isinstance(value, dict) or type(value.get('count')) is not int or value['count'] < 0:
        raise ValueError('nonnegative integer count required')
    return value['count']

